import React from 'react';
import { useNavigate } from 'react-router-dom'; // Using Router for "different pages"
import { 
  Trash2, Map, Calendar, Star, LineChart, Users, 
  HardHat, FileText, Activity, ShieldAlert 
} from 'lucide-react';

const Dashboard = () => {
  const navigate = useNavigate();

  const allTabs = [
    { id: 'bins', label: '01_BIN_MONITORING', icon: <Trash2 size={24}/> },
    { id: 'zones', label: '02_AREAS_&_ZONES', icon: <Map size={24}/> },
    { id: 'schedule', label: '03_COLL_SCHEDULE', icon: <Calendar size={24}/> },
    { id: 'points', label: '04_REWARDS_POINTS', icon: <Star size={24}/> },
    { id: 'analytics', label: '05_SYS_ANALYTICS', icon: <LineChart size={24}/> },
    { id: 'citizens', label: '06_CITIZEN_INFO', icon: <Users size={24}/> },
    { id: 'workers', label: '07_WORKER_NODES', icon: <HardHat size={24}/> },
    { id: 'reports', label: '08_SYS_REPORTS', icon: <FileText size={24}/> },
  ];

  return (
    <div className="w-full min-h-screen bg-[#FDFAD8] p-4 md:p-8 flex items-center justify-center">

      {/* THE SWITCHBOARD CHASSIS */}
      <div className="w-full max-w-[1200px] flex flex-col gap-6 animate-slot">

        {/* BLOCK 1: BRANDED HEADER */}
        <div className="bg-[#AB1717] border-[8px] border-[#47510B] rounded-t-[50px] rounded-b-[20px] p-6 md:p-8 red-stack-shadow shrink-0">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-6">
              <div className="bg-[#FDFAD8] p-3 rounded-2xl border-4 border-[#47510B] shadow-[5px_5px_0_0_#47510B]">
                <ShieldAlert size={40} className="text-[#AB1717]" strokeWidth={2.5} />
              </div>
              <div>
                <p className="text-[10px] md:text-xs font-black uppercase tracking-[0.5em] text-[#FDFAD8] opacity-60 italic mb-1">Command.Master.Console</p>
                <h1 className="text-3xl md:text-5xl font-black italic text-[#FDFAD8] uppercase tracking-tighter leading-none">
                  TRASH<span className="text-[#CAD23C]">2</span>TRACK
                </h1>
              </div>
            </div>
            <Activity className="text-[#CAD23C] animate-pulse hidden sm:block" size={40} />
          </div>
        </div>

        {/* BLOCK 2: THE ADAPTIVE BUTTON GRID */}
        {/* 'grid-cols-1' for mobile, 'grid-cols-2' for small tablets, 'grid-cols-4' for desktop */}
        <div className="bg-[#A1AED1] border-[8px] border-[#47510B] rounded-[40px] p-6 md:p-10 yellow-stack-shadow">
          <p className="text-xs font-black uppercase tracking-[0.3em] text-[#AB1717] mb-6 ml-2">Select_Operational_Node</p>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {allTabs.map((tab) => (
              <button
                key={tab.id}
                onClick={() => navigate(`/${tab.id}`)} // This triggers the full page change
                className="group relative flex flex-col items-center justify-center gap-4 p-8 rounded-[30px] border-[6px] border-[#47510B] bg-[#FDFAD8] transition-all hover:-translate-y-2 hover:bg-[#CAD23C] active:translate-y-1 shadow-[0_12px_0_0_#47510B] hover:shadow-[0_4px_0_0_#47510B]"
              >
                {/* Visual "Button" Indicator Light */}
                <div className="absolute top-4 right-4 w-3 h-3 rounded-full bg-[#47510B] border-2 border-[#AB1717]/20 group-hover:bg-[#AB1717] group-hover:animate-pulse" />

                <div className="text-[#AB1717] group-hover:text-[#47510B] transition-colors scale-125">
                  {tab.icon}
                </div>

                <span className="text-xs md:text-sm font-[1000] uppercase tracking-tighter text-[#47510B] text-center leading-tight">
                  {tab.label.replace(/_/g, ' ')}
                </span>

                {/* Decorative Bottom Groove */}
                <div className="w-12 h-1.5 bg-[#47510B]/10 rounded-full mt-2 group-hover:bg-[#47510B]/20" />
              </button>
            ))}
          </div>
        </div>

        {/* SYSTEM STATUS FOOTER */}
        <div className="flex flex-col items-center gap-2 opacity-60 shrink-0">
            <div className="w-full h-1 bg-[#47510B] rounded-full" />
            <p className="text-[10px] font-black uppercase tracking-[1em] text-[#AB1717]">
              Secure.Terminal.v3.0.Industrial.Admin
            </p>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
